#include <limits.h>
#include <stdio.h>

static int int_from_long(long value, int *result) {
    if (result == NULL || value < INT_MIN || value > INT_MAX) {
        return 0;
    }
    *result = (int)value;
    return 1;
}

int main(void) {
    int converted = 0;
    long input = 120L;

    if (!int_from_long(input, &converted)) {
        puts("out of range");
        return 1;
    }
    printf("converted=%d\n", converted);
    return 0;
}

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>

static uint32_t add_count(uint32_t left, uint32_t right);

static uint32_t add_count(uint32_t left, uint32_t right) {
    return left + right;
}

int main(void) {
    uint32_t total = add_count(UINT32_C(12), UINT32_C(30));
    printf("total=%" PRIu32 "\n", total);
    return 0;
}
